<?php
namespace App\Domain\AI\Knowledge\Services;use App\Domain\AI\Agents\Enums\AgentVersionStatus;use App\Domain\AI\Agents\Models\{Agent,AgentVersion};use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Knowledge\Models\{AgentVersionKnowledgeSource,KnowledgeSourceVersion};use App\Models\User;use Illuminate\Support\Facades\DB;
final class DetachKnowledgeFromAgentVersionService{public function __construct(private AiLifecycleAuthorization$auth){}public function detach(User$actor,Agent$agent,KnowledgeSourceVersion$knowledge):void{DB::transaction(function()use($actor,$agent,$knowledge){$a=$this->auth->authorize($actor);$version=AgentVersion::query()->where('agent_id',$agent->id)->where('status',AgentVersionStatus::Draft->value)->lockForUpdate()->latest('version_number')->firstOrFail();$link=AgentVersionKnowledgeSource::query()->where('agent_version_id',$version->id)->where('knowledge_source_id',$knowledge->knowledge_source_id)->where('knowledge_source_version_id',$knowledge->id)->lockForUpdate()->first();if($link)$link->detachAuthorized($a);});}}
